ject.onEffectGain = function(target, effect)\n    target:setCostume(2438)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:setCostume(0)\nend\n\nreturn itemObject\n"},["scripts/items/piece_of_shiromochi.lua"]={["Path"]="scripts/items/piece_of_shiromochi.lua",["SHA256"]="b6e37085ea0afd9a07013b2158dcaefb4be162311ec7583c39ba29885bb6f8c2",["Text"]="-----------------------------------\n-- ID: 6258\n-- Item: piece_of_shiromochi\n-- Food Effect: 30 Min, All Races\n-----------------------------------\n-- HP + 20 VIT + 3 (Pet & Master)\n-- Accuracy/Ranged Accuracy +14% (cap 70 on master, cap 108 on pet)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.FOOD_ACCP, 14)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 70)\n    effect:addMod(xi.mod.FOOD_RACCP, 14)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 70)\n    target:addPetMod(xi.mod.FOOD_HP, 20)\n    target:addPetMod(xi.mod.VIT, 3)\n    target:addPetMod(xi.mod.FOOD_ACCP, 14)\n    target:addPetMod(xi.mod.FOOD_ACC_CAP, 108)\n    target:addPetMod(xi.mod.FOOD_RACCP, 14)\n    target:addPetMod(xi.mod.FOOD_RACC_CAP, 108)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:delPetMod(xi.mod.FOOD_HP, 20)\n    target:delPetMod(xi.mod.VIT, 3)\n    target:delPetMod(xi.mod.FOOD_ACCP, 14)\n    target:delPetMod(xi.mod.FOOD_ACC_CAP, 108)\n    target:delPetMod(xi.mod.FOOD_RACCP, 14)\n    target:delPetMod(xi.mod.FOOD_RACC_CAP, 108)\nend\n\nreturn itemObject\n"},["scripts/items/piece_of_shiromochi_+1.lua"]={["Path"]="scripts/items/piece_of_shiromochi_+1.lua",["SHA256"]="6b73ba53709cbb9ba5c981b3c7be7b67915dcd06a357b1033d77d072e645b3d4",["Text"]="-----------------------------------\n-- ID: 6259\n-- Item: piece_of_shiromochi_+1\n-- Food Effect: 60 Min, All Races\n-----------------------------------\n-- HP + 30 VIT + 4 (Pet & Master)\n-- Accuracy/Ranged Accuracy +15% (cap 74 on master, cap 114 on pet)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.FOOD_ACCP, 15)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 74)\n    effect:addMod(xi.mod.FOOD_RACCP, 15)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 74)\n    target:addPetMod(xi.mod.FOOD_HP, 30)\n    target:addPetMod(xi.mod.VIT, 4)\n    target:addPetMod(xi.mod.FOOD_ACCP, 15)\n    target:addPetMod(xi.mod.FOOD_ACC_CAP, 114)\n    target:addPetMod(xi.mod.FOOD_RACCP, 15)\n    target:addPetMod(xi.mod.FOOD_RACC_CAP, 114)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:delPetMod(xi.mod.FOOD_HP, 30)\n    target:delPetMod(xi.mod.VIT, 4)\n    target:delPetMod(xi.mod.FOOD_ACCP, 15)\n    target:delPetMod(xi.mod.FOOD_ACC_CAP, 114)\n    target:delPetMod(xi.mod.FOOD_RACCP, 15)\n    target:delPetMod(xi.mod.FOOD_RACC_CAP, 114)\nend\n\nreturn itemObject\n"},["scripts/items/piece_of_slimeulation_candy.lua"]={["Path"]="scripts/items/piece_of_slimeulation_candy.lua",["SHA256"]="0c17264452d1780c748c14719c8b470f47e065ef374ca5a021d175c8b0406f09",["Text"]="-----------------------------------\n-- ID: 6187\n-- Item: Piece of Slimeulation Candy\n-- Food Effect: Costume Slime\n-----------------------------------\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, user)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { duration = 10000, origin = user, subType = 6187 })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    target:setCostume(2881)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:setCostume(0)\nend\n\nreturn itemObject\n"},["scripts/items/piece_of_tarutaru_mochi.lua"]={["Path"]="scripts/items/piece_of_tarutaru_mochi.lua",["SHA256"]="407cc17012f8779adf68a2a535aa79c455a20b32bd76ccd74caa07130e700650",["Text"]="-----------------------------------\n-- ID: 5205\n-- Piece of Tarutaru Mochi\n-- Enchantment: 60Min, Costume - Tarutaru child (male)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 822, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/piece_of_witch_nougat.lua"]={["Path"]="scripts/items/piece_of_witch_nougat.lua",["SHA256"]="1fb13a8c34a54bcd04c49afa9d03d6289b900e2d2d988d51fa9d34e12c2460d7",["Text"]="-----------------------------------\n-- ID: 5645\n-- Item: piece_of_witch_nougat\n-- Food Effect: 1hour, All Races\n-----------------------------------\n-- HP 50\n-- Intelligence 3\n-- Agility -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 50)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.AGI, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/piercing_dagger.lua"]={["Path"]="scripts/items/piercing_dagger.lua",["SHA256"]="eef7da5fb620904fa1d94ca7bf750b307b9214a1f75a8715e629c896cc250e2e",["Text"]="-----------------------------------\n-- ID: 18029\n-- Item: piercing_dagger\n-- Item Effect: Attack +3\n-- Duration: 30 Minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ATTACK_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PIERCING_DAGGER) ~= nil then\n        target:delStatusEffect(xi.effect.ATTACK_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.PIERCING_DAGGER)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.PIERCING_DAGGER) then\n        target:addStatusEffect(xi.effect.ATTACK_BOOST, { power = 3, duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.PIERCING_DAGGER })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/pileus_cell.lua"]={["Path"]="scripts/items/pileus_cell.lua",["SHA256"]="90736bdf2e5f403b1e35da8fb25a5a6bf3f5bcbc94f59965b8ad29f8eece0445",["Text"]="-----------------------------------\n-- Pileus Cell\n-- ID 5381\n-- Removes MND Down effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.DEBILITATION, 0x020)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.DEBILITATION, 0x020, 16)\nend\n\nreturn itemObject\n"},["scripts/items/pinch_of_fanatics_powder.lua"]={["Path"]="scripts/items/pinch_of_fanatics_powder.lua",["SHA256"]="d093c54ac9369db4bfefd305a8aac96e7ca36074f295f7b3139eeb52e10afa0d",["Text"]="-----------------------------------\n-- ID: 5847\n-- Item: pinch_of_fanatics_powder\n-- Item Effect: When applied, grants UDMGPHYS -10000 to party members in range for 60s\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect        = xi.effect.PHYSICAL_SHIELD\n    local duration      = 60\n    local power         = 1\n    local mitigatews    = 1\n\n    target:forMembersInRange(20, function(member)\n        xi.itemUtils.addItemShield(member, power, duration, effect, mitigatews)\n    end)\nend\n\nreturn itemObject\n"},["scripts/items/pinch_of_fools_powder.lua"]={["Path"]="scripts/items/pinch_of_fools_powder.lua",["SHA256"]="cbfcda046d97410110776531b90d3c209192f86e42c5b63f0841796ffe511801",["Text"]="-----------------------------------\n-- ID: 5848\n-- Item: pinch_of_fools_powder\n-- Item Effect: When applied, grants UDMGMAGIC -10000 to party members in range for 60s\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local effect        = xi.effect.MAGIC_SHIELD\n    local duration      = 60\n    local power         = 1\n    local nospellimmune = 0\n\n    target:forMembersInRange(20, function(member)\n        xi.itemUtils.addItemShield(member, power, duration, effect, nospellimmune)\n    end)\nend\n\nreturn itemObject\n"},["scripts/items/pinch_of_mana_powder.lua"]={["Path"]="scripts/items/pinch_of_mana_powder.lua",["SHA256"]="76be28c87fad2ef8663dae00a15c001cee41ee9b6cfef64984272c646067373e",["Text"]="-----------------------------------\n-- ID: 4255\n-- Item: bottle_of_mana_powder\n-- Item Effect: Restores 25% of Maximum MP to Party members within 10'\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:forMembersInRange(10, function(member)\n        member:messageBasic(xi.msg.basic.RECOVERS_MP, 0, member:addMP((member:getMaxMP() / 100) * 25))\n    end)\nend\n\nreturn itemObject\n"},["scripts/items/pinch_of_prism_powder.lua"]={["Path"]="scripts/items/pinch_of_prism_powder.lua",["SHA256"]="2d09e3e5317ddbdddc40a4177d76b47307a4dc08945ac513a2fc408ce3ed7cdf",["Text"]="-----------------------------------\n-- ID: 4164\n-- Prism Powder\n-- When applied, it makes things invisible.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasStatusEffect(xi.effect.INVISIBLE) then\n        target:delStatusEffect(xi.effect.INVISIBLE)\n    end\n\n    target:addStatusEffect(xi.effect.INVISIBLE, { power = 1, duration = math.floor(600 * xi.settings.main.SNEAK_INVIS_DURATION_MULTIPLIER), origin = user, tick = 10 })\nend\n\nreturn itemObject\n"},["scripts/items/pinch_of_rainbow_powder.lua"]={["Path"]="scripts/items/pinch_of_rainbow_powder.lua",["SHA256"]="e439e76f49fc3fd7069ae26a15a50b85563b59c2b1a878cbb9a919ab772d6230",["Text"]="-----------------------------------\n-- ID: 5362\n-- Rainbow Powder\n-- When applied, it makes things invisible.\n-- Removed Medicated status as per https://www.bg-wiki.com/ffxi/Rainbow_Powder\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasStatusEffect(xi.effect.INVISIBLE) then\n        target:delStatusEffect(xi.effect.INVISIBLE)\n    end\n\n    target:addStatusEffect(xi.effect.INVISIBLE, { power = 1, duration = math.floor(600 * xi.settings.main.SNEAK_INVIS_DURATION_MULTIPLIER), origin = user, tick = 10 })\nend\n\nreturn itemObject\n"},["scripts/items/pinwheel_belt.lua"]={["Path"]="scripts/items/pinwheel_belt.lua",["SHA256"]="93f7994f3bf743c397f6ed45bd8923442b18e559644cbc7d4f73af9d94d1976d",["Text"]="-----------------------------------\n-- ID: 15927\n-- pinwheel_belt\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.PINWHEEL, 99 } }) -- pinwheel\nend\n\nreturn itemObject\n"},["scripts/items/pipin_hot_popoto.lua"]={["Path"]="scripts/items/pipin_hot_popoto.lua",["SHA256"]="7db46e1ed16ff99cbba4c4f8272e4182daabf594f3db9a0e1719369264e4bbf8",["Text"]="-----------------------------------\n-- ID: 4282\n-- Item: pipin_hot_popoto\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- HP 25\n-- Vitality 3\n-- HP recovered while healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 25)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.HPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pipira.lua"]={["Path"]="scripts/items/pipira.lua",["SHA256"]="f465f1137f338cb45ce53d6a0715d4073c1f829fdcecba86e1913d684a0cf2e8",["Text"]="-----------------------------------\n-- ID: 5787\n-- Item: pipira\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-- Attack % 14.5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\n    effect:addMod(xi.mod.FOOD_ATTP, 14)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 60)\n    effect:addMod(xi.mod.FOOD_RATTP, 14)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 60)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/piscators_skewer.lua"]={["Path"]="scripts/items/piscators_skewer.lua",["SHA256"]="4cfdb79f0ccdff8b5190a6a7e5c4cff8e52a18fbd4586fc7cd22f4ca3859564c",["Text"]="-----------------------------------\n-- ID: 5983\n-- Item: Piscator's Skewer\n-- Food Effect: 60 Mins, All Races\n-----------------------------------\n-- Dexterity 3\n-- Vitality 4\n-- Defense % 26 Cap 155\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.FOOD_DEFP, 26)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 155)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pitcher_of_homemade_herbal_tea.lua"]={["Path"]="scripts/items/pitcher_of_homemade_herbal_tea.lua",["SHA256"]="13e43a91872c36cd4f91fc39255429e39f7306660f504251fbb4aab4f25a4bac",["Text"]="-----------------------------------\n-- ID: 5221\n-- Item: pitcher_of_homemade_herbal_tea\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Accuracy +12% (cap 80)\n-- Attack +10% (cap 40)\n-- Ranged Accuracy +12% (cap 80)\n-- Ranged Attack +10% (cap 40)\n-- hHP +1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_ACCP, 12)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_ATTP, 10)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 40)\n    effect:addMod(xi.mod.FOOD_RACCP, 12)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RATTP, 10)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 40)\n    effect:addMod(xi.mod.HPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/pixie_mace.lua"]={["Path"]="scripts/items/pixie_mace.lua",["SHA256"]="9d3511679a48bc9d58739aca20fe3f71ae45d424b52a80325e8141d54a680973",["Text"]="-----------------------------------\n-- ID: 17414\n-- Item: Pixie Mace\n-- Additional effect: light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 9,\n        basePower      = math.randomInt(6, 8),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/plantbane.lua"]={["Path"]="scripts/items/plantbane.lua",["SHA256"]="75e1e18ec450eff9d7d068aeecbf1d9766a03f2a7521c8dba8fbab2f3b2e7150",["Text"]="-----------------------------------\n-- ID: 16720\n-- Item: Plantbane\n-- Additional effect: fire damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    if target:getEcosystem() ~= xi.ecosystem.PLANTOID then\n        return 0, 0, 0\n    end\n\n    local pTable =\n    {\n        chance         = 10, -- TODO: this probably scales with dINT but sample sizes are insanely low.\n        basePower      = math.randomInt(9, 12),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.FIRE,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/plate_of_anchovies.lua"]={["Path"]="scripts/items/plate_of_anchovies.lua",["SHA256"]="16d0bdd2fbc1a4ba40d6b7fbbe1d1944b0baa0b932b55d6219450d9f32ba8b8d",["Text"]="-----------------------------------\n-- ID: 5652\n-- Item: plate_of_anchovies\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- Dexterity 1\n-- Mind -3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.MND, -3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/plate_of_barnacle_paella.lua"]={["Path"]="scripts/items/plate_of_barnacle_paella.lua",["SHA256"]="3ee18f85c759d68ee91004b54e5c1241286741dabd75d91fa1291a3c8bd2f19f",["Text"]="-----------------------------------\n-- ID: 5974\n-- Item: Plate of Barnacle Paella\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- HP 40\n-- Vitality 5\n-- Mind -1\n-- Charisma -1\n-- Defense % 25 Cap 150\n-- Undead Killer 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 40)\n    effect:addMod(xi.mod.VIT, 5)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.CHR, -1)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 150)\n    effect:addMod(xi.mod.UNDEAD_KILLER, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/plate_of_beef_paella.lua"]={["Path"]="scripts/items/plate_of_beef_paella.lua",["SHA256"]="bba1b2a87cbdb6c197260b6b03ae8ddaa69116b41b35ed5d37b82b50b14b0c8c",["Text"]="-----------------------------------\n-- ID: 5972\n-- Item: Plate of Beef 